exercise.solution:
def reponse_script(responses, tour):
    if not responses or tour<1:raise ValueError('scénario invalide')
    return responses[min(tour-1,len(responses)-1)]

exercise.check:
assert reponse_script(['outil','final'],1)=='outil'
assert reponse_script(['outil','final'],2)=='final'
assert reponse_script(['outil','final'],9)=='final'
try:reponse_script([],1)
except ValueError:pass
else:raise AssertionError('scénario vide')
